"""Freeze both reused development cohorts before new model calls."""
import pathlib,argparse,datetime,subprocess
from gr_common import read,sha,write
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--stage',required=True);s=pathlib.Path(ap.parse_args().stage);rt=s.parent.parent;datasets={}
 for name,stage in [('gossipcop','target_rewriter_20261114_attempt1'),('yelpchi','yelpchi_validation_20261115_attempt1')]:
  parent=rt/'runs'/stage;old=read(parent/'protocol.json');assert read(parent/'guardian_receipt.json')['status']=='completed'
  inputs={str(parent/n):sha(parent/n) for n in ['protocol.json','main/result.json','main/sealed_before_victim.json']}
  seal=read(parent/'main/sealed_before_victim.json')
  for e in seal['entries']:inputs[str(parent/'main'/e['path'])]=e['sha256']
  for n,h in old['sources'].items():inputs[str(parent/'source'/n)]=h
  datasets[name]=dict(parent=str(parent),inputs=inputs,valid_groups=old['valid_groups'],preflight_groups=old['train_groups'][:2],seeds=old['seeds'],occurrences=571 if name=='gossipcop' else 230,unique_targets=240 if name=='gossipcop' else 230)
 manifest=read(s/'source_manifest.json');assert subprocess.check_output(['git','rev-parse','HEAD'],cwd=rt,text=True).strip()=='ca093d8b12ea153a076b02bbdbc4ede58508560c'
 p=dict(schema='gradient_retrieval_v1',frozen_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),runtime_root=str(rt),runtime_commit='ca093d8b12ea153a076b02bbdbc4ede58508560c',source_commit=manifest['source_commit'],sources=manifest['files'],datasets=datasets,TEST_allowed=False,arms=['native','single_neural','rewriter','softplus','random_softplus','boundary','random_boundary','uniform','random_uniform'],primary_candidate='boundary',settings=dict(regions=3,horizon=2,shortlist_per_region=8,boundary_temperature=1,stop_gain=1e-5,sequence_tolerance=1e-5,logit_tolerance=2e-5),resources=dict(CPU_threads=4,nice=10,GPU_hours=0,API_calls=0,preflight_seconds=1800,selection_seconds=14400,evaluation_seconds=3600,audit_seconds=900,automatic_retry=False),caps=dict(per_dataset_physical_builds=4000,per_dataset_teacher_contexts=32000,per_dataset_backward_calls=800,per_dataset_official_VALID=1728),primary='Boundary candidate must exceed native, existing single neural, existing two-step rewriter and its own matched random in EACH dataset by pooled MR. Report its difference against uniform shortlist search too, all repeats and all failed contrasts. No outcome-adaptive case exclusion.',limitations=['Reused development cohorts have already been inspected. This is exploratory adaptive development, not untouched confirmation.','One fixed author checkpoint and one independent TRAIN-fitted teacher per dataset; three capture repetitions are not independent author trainings or independent target samples.','HotFlip-inspired full legal TRAIN-benign pool retrieval is a downstream optimizer, not a newly trained neural model or first-novelty claim.','Uniform shortlist uses the same pool, regions, horizon and number of verified surrogate contexts per step. Gradients and algebraic pool scoring are extra computation. Matched random uses the exact selected donor slots and exchange dose.','All final choices for BOTH datasets seal before any new official victim call. Native and existing models use exact saved graphs. No TEST/API/GPU/new teacher or upstream generation.','Affine template equivalence must pass fixed TRAIN checks, then EVERY final new/random graph is physically verified before official scoring. Equality is to the locked canonical implementation, not an independent full-graph semantics theorem.','Sequential dataset phases; no tuning after partial results. A later iteration requires a new evidence-based protocol. No fixed maximum claim of eventual success.'])
 write(s/'protocol.json',p);print(dict(status='frozen',protocol_sha256=sha(s/'protocol.json'),model_calls=0))
if __name__=='__main__':main()
